DECLARE
    V_REQUEST_ID RAW(16);
    V_MESSAGE    VARCHAR2(4000);
    V_MSG        VARCHAR2(4000);
    V_JSON       CLOB := {{ JSON.stringify(JS_MMS_MAKER_REQUEST.getRequestData()) }};
BEGIN
    TALY_BO_REP.MMS_ONBOARDING_PKG.CREATE_REQUEST(
        P_REQUEST_JSON => V_JSON,
        P_REQUEST_ID   => V_REQUEST_ID,
        P_MESSAGE      => V_MESSAGE
    );
    SELECT V_REQUEST_ID into V_MESSAGE FROM DUAL;
    -- Return the message as a result set for Appsmith to read
END;
